#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    long long maxProduct(std::vector<int>& nums) {
        std::vector<int> uniq = nums;
        std::sort(uniq.begin(), uniq.end(), std::greater<int>());
        uniq.erase(std::unique(uniq.begin(), uniq.end()), uniq.end());

        long long best = 0;
        int n = uniq.size();
        for (int i = 0; i < n; ++i) {
            long long a = uniq[i];
            if (a * a <= best) break;
            for (int j = i + 1; j < n; ++j) {
                long long b = uniq[j];
                if ((a & b) == 0) {
                    best = std::max(best, a * b);
                    break;
                }
            }
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public long maxProduct(int[] nums) {
        Integer[] boxed = Arrays.stream(nums).distinct().boxed().toArray(Integer[]::new);
        Arrays.sort(boxed, Collections.reverseOrder());

        long best = 0;
        int n = boxed.length;
        for (int i = 0; i < n; i++) {
            long a = boxed[i];
            if (a * a <= best) break;
            for (int j = i + 1; j < n; j++) {
                long b = boxed[j];
                if ((a & b) == 0) {
                    best = Math.max(best, a * b);
                    break;
                }
            }
        }
        return best;
    }
}

var maxProduct = function(nums) {
    const uniq = Array.from(new Set(nums)).sort((a, b) => b - a);
    let best = 0;
    const n = uniq.length;

    for (let i = 0; i < n; i++) {
        const a = uniq[i];
        if (a * a <= best) break;
        for (let j = i + 1; j < n; j++) {
            const b = uniq[j];
            if ((a & b) === 0) {
